<?php
/**
 * ============================================================================
 * ARCHITECTURE & MODULE OVERVIEW: compile_ebooks.php
 * ============================================================================
 * Purpose:
 * Takes the master [novel-slug]-complete.md files generated by lump_narratives
 * and compiles them into final .epub and .pdf distributions.
 * 
 * Logic:
 * 1. Image Resolution: Replaces {{CDN}} with the absolute system path to 
 *    the raggiesoft-assets directory so Pandoc can embed the image binaries.
 * 2. Tag Translation: Translates custom web tags (<aac>, <lang>, <sgn>) into
 *    standard markdown italics with inline context for offline readers.
 * 3. Execution: Triggers Pandoc to build the final deliverables into the
 *    public CDN delivery folders.
 * ============================================================================
 */

$workspaceRoot = dirname(dirname(__DIR__)); // Go up from raggiesoft-narratives/scripts to workspace root
$lumpDir = $workspaceRoot . '/raggiesoft-narratives/books-ai-lump';
$outBaseDir = $workspaceRoot . '/raggiesoft-assets/raggiesoft-books/books';

if (!is_dir($lumpDir)) {
    die("Error: Lump directory ($lumpDir) not found. Run lump_narratives.php first.\n");
}

$dirs = array_filter(glob($lumpDir . '/*'), 'is_dir');

foreach ($dirs as $novelDir) {
    $slug = basename($novelDir);
    $mdFile = $novelDir . '/' . $slug . '-complete.md';
    
    if (!file_exists($mdFile)) {
        continue;
    }
    
    echo "Processing '{$slug}'...\n";
    $content = file_get_contents($mdFile);
    
    // --- 1. IMAGE RESOLUTION ---
    // Pandoc needs absolute or valid relative paths to embed images locally.
    // Replace {{CDN}} with the absolute path to the local assets repository.
    $localCdnPath = $workspaceRoot . '/raggiesoft-assets';
    $content = str_replace('{{CDN}}', $localCdnPath, $content);
    
    // Strip trailing URL modifiers like #fullwidth or ?width=100 that break Pandoc's file locator
    $content = preg_replace('/(\.(?:jpg|jpeg|png|gif|webp))(?:#[^\s\)]+|\?[^\s\)]+)/i', '$1', $content);
    
    // --- 2. CUSTOM NARRATIVE TAGS ---
    // <aac> tags: Convert to standard italics (often used for synthesized voices in literature)
    $content = preg_replace('/<aac>(.*?)<\/aac>/is', '*$1*', $content);
    
    // <asl>, <sgn>, <sms>: Convert to standard italics
    $content = preg_replace('/<(asl|sgn|sms)>(.*?)<\/\1>/is', '*$2*', $content);
    
    // <lang> tags: Convert to italics and inject the translation in parentheses
    // e.g., <lang="fr-CA" trans="Good morning">Bonjour</lang> -> *Bonjour* (Good morning)
    $content = preg_replace_callback('/<lang(?:[^>]*?)trans="([^"]+)"(?:[^>]*?)>(.*?)<\/lang>/is', function($matches) {
        $translation = trim($matches[1]);
        $original = trim($matches[2]);
        return "*{$original}* ({$translation})";
    }, $content);
    
    // Catch-all for <lang> tags that don't have a translation attribute
    $content = preg_replace('/<lang[^>]*>(.*?)<\/lang>/is', '*$1*', $content);
    
    // --- 3. PREPARE FOR PANDOC ---
    // Save the pre-processed markdown to a temporary file for Pandoc to ingest
    $tmpMd = $novelDir . '/' . $slug . '-pandoc-stage.md';
    file_put_contents($tmpMd, $content);
    
    // Ensure the destination CDN directory exists
    $outDir = $outBaseDir . '/' . $slug;
    if (!is_dir($outDir)) {
        mkdir($outDir, 0755, true);
    }
    
    $epubFile = $outDir . '/' . $slug . '.epub';
    $pdfFile = $outDir . '/' . $slug . '.pdf';
    
    // --- 4. GENERATE EPUB ---
    echo "  -> Generating EPUB...\n";
    $epubCmd = sprintf(
        'pandoc %s -o %s --toc --toc-depth=3 2>&1',
        escapeshellarg($tmpMd),
        escapeshellarg($epubFile)
    );
    exec($epubCmd, $epubOutput, $epubReturn);
    if ($epubReturn !== 0) {
        echo "  [Error] EPUB generation failed for $slug\n";
        echo implode("\n", $epubOutput) . "\n";
    } else {
        echo "  [Success] Saved to " . str_replace($workspaceRoot, '', $epubFile) . "\n";
    }
    
    // --- 5. GENERATE PDF ---
    // Note: Pandoc requires a PDF engine like weasyprint, pdflatex, or wkhtmltopdf to create PDFs.
    echo "  -> Generating PDF...\n";
    
    // Try using typst or weasyprint or pdflatex. We'll default to standard pandoc pdf call.
    // If the system lacks an engine, this will gracefully warn the user.
    $pdfCmd = sprintf(
        'pandoc %s -o %s --toc --toc-depth=3 2>&1',
        escapeshellarg($tmpMd),
        escapeshellarg($pdfFile)
    );
    exec($pdfCmd, $pdfOutput, $pdfReturn);
    if ($pdfReturn !== 0) {
        echo "  [Warning] PDF generation failed for $slug (Likely missing a PDF engine like WeasyPrint or BasicTeX).\n";
        // Optionally output the exact error for debugging
        // echo implode("\n", $pdfOutput) . "\n";
    } else {
        echo "  [Success] Saved to " . str_replace($workspaceRoot, '', $pdfFile) . "\n";
    }
    
    // Cleanup the temporary staging file
    unlink($tmpMd);
    echo "\n";
}

echo "========================================================\n";
echo "E-Book Compilation Complete!\n";
echo "========================================================\n";
?>
